# Multi-Part Changes Implementation: HR Rotational Development Program Framework

## Implementation Overview

The rotational development framework enhances the existing multi-agent architecture through eight interconnected modifications that establish specialty cultivation based on historical field engagement while maintaining cross-functional development opportunities.

## Part 1: Enhanced BaseAgent with Rotational Capabilities

**File: `src/main/java/com/IDE/plugin/ai/multiagent/agent/EnhancedBaseAgent.java`**

```java
// Add to existing EnhancedBaseAgent class
private final RotationalProfile rotationalProfile;
private final SpecialtyTracker specialtyTracker;
private final Map<String, DomainExperience> domainHistory;

// Enhanced constructor addition
protected EnhancedBaseAgent(String agentId, AgentRole role) {
    super(agentId, role);
    this.rotationalProfile = new RotationalProfile(agentId, role);
    this.specialtyTracker = new SpecialtyTracker(agentId);
    this.domainHistory = new ConcurrentHashMap<>();

    initializeDomainTracking();
}

private void initializeDomainTracking() {
    // Initialize domain experience tracking
    for (String domain : getAvailableDomains()) {
        domainHistory.put(domain, new DomainExperience(domain));
    }
}

protected void recordDomainActivity(String domain, String activity, double impact) {
    DomainExperience experience = domainHistory.get(domain);
    if (experience != null) {
        experience.recordActivity(activity, impact, System.currentTimeMillis());
        specialtyTracker.updateDomainEngagement(domain, experience);

        // Update rotational profile
        rotationalProfile.recordDomainWork(domain, impact);
    }
}

public String getPrimarySpecialty() {
    return specialtyTracker.calculatePrimarySpecialty(domainHistory);
}

public RotationalAssignmentEligibility getRotationalEligibility() {
    return rotationalProfile.calculateEligibility(domainHistory);
}

// Inner classes for domain tracking
private static class DomainExperience {
    private final String domain;
    private final List<ActivityRecord> activities;
    private long totalEngagementTime;
    private double cumulativeImpact;
    private long firstEngagement;
    private long lastEngagement;

    public DomainExperience(String domain) {
        this.domain = domain;
        this.activities = new CopyOnWriteArrayList<>();
        this.totalEngagementTime = 0;
        this.cumulativeImpact = 0.0;
        this.firstEngagement = 0;
        this.lastEngagement = 0;
    }

    public void recordActivity(String activity, double impact, long timestamp) {
        activities.add(new ActivityRecord(activity, impact, timestamp));
        cumulativeImpact += impact;

        if (firstEngagement == 0) {
            firstEngagement = timestamp;
        }
        lastEngagement = timestamp;
        totalEngagementTime = lastEngagement - firstEngagement;
    }

    public long getHistoricalDepth() {
        return totalEngagementTime;
    }

    public double getExpertiseLevel() {
        return cumulativeImpact / Math.max(1, activities.size());
    }
}

private static class ActivityRecord {
    private final String activity;
    private final double impact;
    private final long timestamp;

    public ActivityRecord(String activity, double impact, long timestamp) {
        this.activity = activity;
        this.impact = impact;
        this.timestamp = timestamp;
    }
}
