## Part 2: Memory System Enhancement for Historical Expertise

**File: `src/main/java/com/IDE/plugin/ai/multiagent/memory/core/MemoryStateManager.java`**

```java
// Add to existing MemoryStateManager class
private final HistoricalExpertiseIndex expertiseIndex;
private final DomainKnowledgeRepository domainRepository;

// Enhanced constructor addition
public MemoryStateManager(TrustVerificationService trustService) {
    // ... existing initialization
    this.expertiseIndex = new HistoricalExpertiseIndex();
    this.domainRepository = new DomainKnowledgeRepository(this);
}

public void recordDomainExpertise(String agentId, String domain, 
                                 Object knowledgeArtifact, double confidence) {
    MemoryState expertiseState = new MemoryState(
        generateExpertiseKey(agentId, domain),
        knowledgeArtifact,
        MemoryType.SEMANTIC,
        agentId,
        TrustLevel.VERIFIED
    );

    // Store in semantic memory for long-term retention
    semanticMemory.store(expertiseState);

    // Update expertise index
    expertiseIndex.recordExpertise(agentId, domain, confidence, System.currentTimeMillis());

    // Update domain repository
    domainRepository.addKnowledgeContribution(agentId, domain, knowledgeArtifact);
}

public Map<String, Double> getAgentExpertiseProfile(String agentId) {
    return expertiseIndex.calculateExpertiseProfile(agentId);
}

public String calculateAgentSpecialty(String agentId) {
    Map<String, Long> domainHistory = expertiseIndex.getDomainEngagementHistory(agentId);

    return domainHistory.entrySet().stream()
        .max(Map.Entry.comparingByValue())
        .map(Map.Entry::getKey)
        .orElse("GENERALIST");
}

private String generateExpertiseKey(String agentId, String domain) {
    return String.format("expertise.%s.%s.%d", agentId, domain, System.currentTimeMillis());
}

// Inner class for expertise tracking
private static class HistoricalExpertiseIndex {
    private final Map<String, Map<String, List<ExpertiseRecord>>> agentDomainHistory;

    public HistoricalExpertiseIndex() {
        this.agentDomainHistory = new ConcurrentHashMap<>();
    }

    public void recordExpertise(String agentId, String domain, double confidence, long timestamp) {
        agentDomainHistory.computeIfAbsent(agentId, k -> new ConcurrentHashMap<>())
            .computeIfAbsent(domain, k -> new CopyOnWriteArrayList<>())
            .add(new ExpertiseRecord(confidence, timestamp));
    }

    public Map<String, Long> getDomainEngagementHistory(String agentId) {
        Map<String, List<ExpertiseRecord>> domains = agentDomainHistory.get(agentId);
        if (domains == null) return Collections.emptyMap();

        return domains.entrySet().stream()
            .collect(Collectors.toMap(
                Map.Entry::getKey,
                entry -> calculateEngagementDepth(entry.getValue())
            ));
    }

    private long calculateEngagementDepth(List<ExpertiseRecord> records) {
        if (records.isEmpty()) return 0;

        long earliest = records.stream().mapToLong(r -> r.timestamp).min().orElse(0);
        long latest = records.stream().mapToLong(r -> r.timestamp).max().orElse(0);

        return latest - earliest; // Historical depth in milliseconds
    }
}

private static class ExpertiseRecord {
    final double confidence;
    final long timestamp;

    ExpertiseRecord(double confidence, long timestamp) {
        this.confidence = confidence;
        this.timestamp = timestamp;
    }
}
