// Add to existing ReputationManager class
private final RotationalCompetencyTracker competencyTracker;
private final Map<String, SpecialtyCredentials> specialtyCredentials;

// Enhanced constructor addition
public ReputationManager(ReputationConfig config) {
    // ... existing initialization
    this.competencyTracker = new RotationalCompetencyTracker();
    this.specialtyCredentials = new ConcurrentHashMap<>();
}

public void recordRotationalAssignment(String agentId, String fromDomain, 
                                     String toDomain, RotationalObjective objective) {
    TrustEvent rotationalEvent = new TrustEvent(
        eventCounter.incrementAndGet(),
        agentId,
        TrustEventType.ROTATIONAL_ASSIGNMENT,
        0.05, // Small positive impact for learning opportunity
        Instant.now(),
        Map.of(
            "fromDomain", fromDomain,
            "toDomain", toDomain,
            "objective", objective.toString()
        )
    );

    recordTrustEvent(agentId, TrustEventType.ROTATIONAL_ASSIGNMENT, 0.05, 
                    rotationalEvent.getMetadata());

    competencyTracker.recordAssignment(agentId, fromDomain, toDomain, objective);
}

public void recordSpecialtyAchievement(String agentId, String domain, 
                                     SpecialtyLevel level, Map<String, Object> evidence) {
    SpecialtyCredentials credentials = specialtyCredentials.computeIfAbsent(
        agentId, k -> new SpecialtyCredentials(agentId)
    );

    credentials.addSpecialty(domain, level, evidence);

    // Specialty achievement significantly boosts trust
    double trustImpact = calculateSpecialtyTrustImpact(level);
    recordTrustEvent(agentId, TrustEventType.SPECIALTY_ACHIEVED, trustImpact,
                    Map.of("domain", domain, "level", level.toString()));
}

private double calculateSpecialtyTrustImpact(SpecialtyLevel level) {
    switch (level) {
        case PRACTITIONER: return 0.1;
        case SPECIALIST: return 0.2;
        case EXPERT: return 0.35;
        case MASTER: return 0.5;
        default: return 0.0;
    }
}

public TrustMetrics getEnhancedTrustMetrics(String agentId) {
    TrustMetrics baseTrust = getTrustMetrics(agentId);
    RotationalProfile rotationalProfile = competencyTracker.getProfile(agentId);
    SpecialtyCredentials credentials = specialtyCredentials.get(agentId);

    return new EnhancedTrustMetrics(baseTrust, rotationalProfile, credentials);
}

// Inner classes for rotational tracking
private static class RotationalCompetencyTracker {
    private final Map<String, List<RotationalAssignment>> agentAssignments;

    public RotationalCompetencyTracker() {
        this.agentAssignments = new ConcurrentHashMap<>();
    }

    public void recordAssignment(String agentId, String fromDomain, 
                               String toDomain, RotationalObjective objective) {
        agentAssignments.computeIfAbsent(agentId, k -> new CopyOnWriteArrayList<>())
            .add(new RotationalAssignment(fromDomain, toDomain, objective, Instant.now()));
    }

    public RotationalProfile getProfile(String agentId) {
        List<RotationalAssignment> assignments = agentAssignments.getOrDefault(
            agentId, Collections.emptyList()
        );
        return new RotationalProfile(agentId, assignments);
    }
}

public enum SpecialtyLevel {
    PRACTITIONER(1, "Basic proficiency with supervised guidance"),
    SPECIALIST(2, "Independent operation with domain expertise"),  
    EXPERT(3, "Advanced mastery with innovation capability"),
    MASTER(4, "Organizational authority with mentoring responsibility");

    private final int level;
    private final String description;

    SpecialtyLevel(int level, String description) {
        this.level = level;
        this.description = description;
    }
}

public enum RotationalObjective {
    SKILL_BROADENING,
    CROSS_FUNCTIONAL_UNDERSTANDING,
    LEADERSHIP_DEVELOPMENT,
    INNOVATION_EXPOSURE,
    KNOWLEDGE_TRANSFER
}
