## Part 4: Agent Coordinator Service Enhancement

**File: `src/main/java/com/IDE/plugin/ai/multiagent/services/AgentCoordinatorService.java`**

```java
// Add to existing AgentCoordinatorService class
private final RotationalDevelopmentManager rotationalManager;
private final SpecialtyAssignmentOptimizer assignmentOptimizer;

// Enhanced constructor addition
public AgentCoordinatorService(/* existing parameters */) {
    // ... existing initialization
    this.rotationalManager = new RotationalDevelopmentManager(
        trustManager, memoryManager, eventBus
    );
    this.assignmentOptimizer = new SpecialtyAssignmentOptimizer(rotationalManager);
}

public CompletableFuture<RotationalAssignment> initiateRotationalAssignment(
        String agentId, RotationalDevelopmentRequest request) {

    return CompletableFuture.supplyAsync(() -> {
        try {
            // Validate agent eligibility
            Agent agent = registeredAgents.get(agentId);
            if (agent == null) {
                throw new IllegalArgumentException("Agent not found: " + agentId);
            }

            // Check rotational eligibility
            RotationalEligibility eligibility = rotationalManager.assessEligibility(agentId);
            if (!eligibility.isEligible()) {
                throw new IllegalStateException("Agent not eligible for rotation: " + 
                                              eligibility.getReason());
            }

            // Create rotational assignment
            RotationalAssignment assignment = rotationalManager.createAssignment(
                agentId, request.getTargetDomain(), request.getDuration(), 
                request.getLearningObjectives()
            );

            // Update agent assignment
            updateAgentAssignment(agentId, assignment);

            // Record in administrative history
            recordRotationalAssignment(agentId, assignment);

            return assignment;

        } catch (Exception e) {
            logger.error("Failed to create rotational assignment for agent: {}", agentId, e);
            throw new ServiceException("Rotational assignment failed", e);
        }
    }, managementExecutor);
}

private void updateAgentAssignment(String agentId, RotationalAssignment assignment) {
    Agent agent = registeredAgents.get(agentId);
    if (agent instanceof EnhancedBaseAgent) {
        EnhancedBaseAgent enhancedAgent = (EnhancedBaseAgent) agent;
        enhancedAgent.beginRotationalAssignment(assignment);
    }
}

public Map<String, String> getAgentSpecialties() {
    return registeredAgents.entrySet().stream()
        .collect(Collectors.toMap(
            Map.Entry::getKey,
            entry -> calculateAgentSpecialty(entry.getValue())
        ));
}

private String calculateAgentSpecialty(Agent agent) {
    if (agent instanceof EnhancedBaseAgent) {
        return ((EnhancedBaseAgent) agent).getPrimarySpecialty();
    }
    return "GENERAL";
}

public CompletableFuture<SpecialtyTeam> assembleSpecialtyTeam(SpecialtyTeamRequest request) {
    return assignmentOptimizer.optimizeTeamComposition(
        request.getRequiredSpecialties(),
        request.getRotationalQuota(),
        registeredAgents
    );
}
