## Part 5: New RotationalDevelopmentManager

**File: `src/main/java/com/IDE/plugin/ai/multiagent/development/RotationalDevelopmentManager.java`**

```java
package com.IDE.plugin.ai.multiagent.development;

import com.IDE.plugin.ai.multiagent.trust.TrustManager;
import com.IDE.plugin.ai.multiagent.memory.MemoryManager;
import com.IDE.plugin.ai.multiagent.event.EventBus;

import java.time.LocalDateTime;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

/**
 * Manages rotational development programs that balance specialty cultivation
 * with cross-functional skill development.
 */
public class RotationalDevelopmentManager {

    private final TrustManager trustManager;
    private final MemoryManager memoryManager;
    private final EventBus eventBus;

    private final Map<String, RotationalProgram> activePrograms;
    private final Map<String, List<RotationalAssignment>> agentAssignmentHistory;
    private final ScheduledExecutorService scheduler;
    private final RotationalPolicyEngine policyEngine;

    public RotationalDevelopmentManager(TrustManager trustManager, 
                                      MemoryManager memoryManager, EventBus eventBus) {
        this.trustManager = trustManager;
        this.memoryManager = memoryManager;
        this.eventBus = eventBus;
        this.activePrograms = new ConcurrentHashMap<>();
        this.agentAssignmentHistory = new ConcurrentHashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(2);
        this.policyEngine = new RotationalPolicyEngine();

        initializePrograms();
    }

    private void initializePrograms() {
        // Initialize standard rotational programs based on enterprise patterns
        createProgram("TalentDevelopment", Arrays.asList(
            new ProgramRotation("Learning_Culture", Duration.ofDays(60), 
                              "Design engaging experiences and support leadership development"),
            new ProgramRotation("Multicultural_Affairs", Duration.ofDays(60), 
                              "Organize DEIB events and implement inclusive practices"),
            new ProgramRotation("Talent_Acquisition", Duration.ofDays(60), 
                              "Master sourcing techniques and employer branding")
        ));

        createProgram("TechnicalSpecialization", Arrays.asList(
            new ProgramRotation("Architecture_Design", Duration.ofDays(90),
                              "System design and architectural decision making"),
            new ProgramRotation("Code_Development", Duration.ofDays(90),
                              "Implementation and optimization expertise"),
            new ProgramRotation("Quality_Assurance", Duration.ofDays(60),
                              "Testing strategies and quality management")
        ));
    }

    public RotationalEligibility assessEligibility(String agentId) {
        // Get agent's current specialty depth
        List<RotationalAssignment> history = agentAssignmentHistory.getOrDefault(
            agentId, Collections.emptyList()
        );

        // Calculate specialty strength
        Map<String, Long> domainEngagement = calculateDomainEngagement(agentId);
        String primarySpecialty = findPrimarySpecialty(domainEngagement);
        long specialtyDepth = domainEngagement.getOrDefault(primarySpecialty, 0L);

        // Apply policy rules
        RotationalPolicy policy = policyEngine.getPolicy(agentId);
        return policy.assessEligibility(specialtyDepth, history);
    }

    public RotationalAssignment createAssignment(String agentId, String targetDomain, 
                                               Duration duration, List<String> objectives) {
        String currentSpecialty = getCurrentSpecialty(agentId);

        RotationalAssignment assignment = new RotationalAssignment(
            generateAssignmentId(),
            agentId,
            currentSpecialty,
            targetDomain,
            duration,
            objectives,
            LocalDateTime.now()
        );

        // Record assignment
        agentAssignmentHistory.computeIfAbsent(agentId, k -> new CopyOnWriteArrayList<>())
            .add(assignment);

        // Schedule completion tracking
        scheduler.schedule(() -> completeAssignment(assignment), 
                         duration.toMillis(), TimeUnit.MILLISECONDS);

        return assignment;
    }

    private Map<String, Long> calculateDomainEngagement(String agentId) {
        // Integration with memory manager to get historical engagement data
        return memoryManager.getAgentDomainHistory(agentId);
    }

    private String findPrimarySpecialty(Map<String, Long> domainEngagement) {
        return domainEngagement.entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey)
            .orElse("GENERALIST");
    }

    private String getCurrentSpecialty(String agentId) {
        Map<String, Long> engagement = calculateDomainEngagement(agentId);
        return findPrimarySpecialty(engagement);
    }

    private void completeAssignment(RotationalAssignment assignment) {
        assignment.markCompleted();

        // Evaluate assignment success
        AssignmentEvaluation evaluation = evaluateAssignment(assignment);

        // Update trust based on performance
        updateTrustFromRotation(assignment, evaluation);

        // Publish completion event
        eventBus.publish(new RotationalEvent(
            RotationalEvent.Type.ASSIGNMENT_COMPLETED,
            assignment.getAgentId(),
            Map.of("assignment", assignment, "evaluation", evaluation)
        ));
    }

    private AssignmentEvaluation evaluateAssignment(RotationalAssignment assignment) {
        // Evaluate learning objectives achievement
        double objectiveCompletion = calculateObjectiveCompletion(assignment);

        // Measure cross-functional knowledge gained
        double knowledgeGain = measureKnowledgeTransfer(assignment);

        // Assess collaboration effectiveness
        double collaborationScore = assessCollaborationEffectiveness(assignment);

        return new AssignmentEvaluation(
            assignment.getId(),
            objectiveCompletion,
            knowledgeGain,
            collaborationScore,
            LocalDateTime.now()
        );
    }

    private double calculateObjectiveCompletion(RotationalAssignment assignment) {
        // Measure how well learning objectives were achieved
        return 0.85; // Placeholder - would integrate with actual assessment mechanisms
    }

    private double measureKnowledgeTransfer(RotationalAssignment assignment) {
        // Quantify knowledge gained in target domain
        return 0.78; // Placeholder - would analyze memory artifacts and knowledge contributions
    }

    private double assessCollaborationEffectiveness(RotationalAssignment assignment) {
        // Evaluate how effectively agent collaborated during rotation
        return 0.82; // Placeholder - would analyze communication patterns and peer feedback
    }

    private void updateTrustFromRotation(RotationalAssignment assignment, 
                                       AssignmentEvaluation evaluation) {
        double trustImpact = (evaluation.getObjectiveCompletion() + 
                            evaluation.getKnowledgeGain() + 
                            evaluation.getCollaborationScore()) / 3.0 * 0.1;

        trustManager.updateAgentTrust(assignment.getAgentId(), trustImpact, 
                                    "Rotational assignment completion");
    }

    private String generateAssignmentId() {
        return "ROT_" + System.currentTimeMillis() + "_" + 
               ThreadLocalRandom.current().nextInt(1000, 9999);
    }

    // Supporting classes
    public static class RotationalAssignment {
        private final String id;
        private final String agentId;
        private final String sourceDomain;
        private final String targetDomain;
        private final Duration duration;
        private final List<String> learningObjectives;
        private final LocalDateTime startTime;
        private LocalDateTime completionTime;
        private boolean completed;

        public RotationalAssignment(String id, String agentId, String sourceDomain,
                                  String targetDomain, Duration duration, 
                                  List<String> objectives, LocalDateTime startTime) {
            this.id = id;
            this.agentId = agentId;
            this.sourceDomain = sourceDomain;
            this.targetDomain = targetDomain;
            this.duration = duration;
            this.learningObjectives = new ArrayList<>(objectives);
            this.startTime = startTime;
            this.completed = false;
        }

        public void markCompleted() {
            this.completed = true;
            this.completionTime = LocalDateTime.now();
        }

        // Getters
        public String getId() { return id; }
        public String getAgentId() { return agentId; }
        public String getTargetDomain() { return targetDomain; }
        public boolean isCompleted() { return completed; }
    }

    public static class RotationalEligibility {
        private final boolean eligible;
        private final String reason;
        private final Map<String, Object> requirements;

        public RotationalEligibility(boolean eligible, String reason, 
                                   Map<String, Object> requirements) {
            this.eligible = eligible;
            this.reason = reason;
            this.requirements = requirements;
        }

        public boolean isEligible() { return eligible; }
        public String getReason() { return reason; }
    }
}
