## Part 6: New SpecialtyTracker System

**File: `src/main/java/com/IDE/plugin/ai/multiagent/specialty/SpecialtyTracker.java`**

```java
package com.IDE.plugin.ai.multiagent.specialty;

import java.time.LocalDateTime;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;

/**
 * Tracks and measures agent specialty development based on historical
 * engagement depth and expertise demonstration.
 */
public class SpecialtyTracker {

    private final String agentId;
    private final Map<String, DomainEngagementMetrics> domainMetrics;
    private final List<SpecialtyMilestone> milestones;
    private final SpecialtyCalculationEngine calculationEngine;

    public SpecialtyTracker(String agentId) {
        this.agentId = agentId;
        this.domainMetrics = new ConcurrentHashMap<>();
        this.milestones = new ArrayList<>();
        this.calculationEngine = new SpecialtyCalculationEngine();
    }

    public void updateDomainEngagement(String domain, DomainExperience experience) {
        DomainEngagementMetrics metrics = domainMetrics.computeIfAbsent(
            domain, k -> new DomainEngagementMetrics(domain)
        );

        metrics.updateFromExperience(experience);

        // Check for milestone achievements
        checkMilestones(domain, metrics);
    }

    public String calculatePrimarySpecialty(Map<String, DomainExperience> domainHistory) {
        Map<String, Double> specialtyScores = new HashMap<>();

        for (Map.Entry<String, DomainExperience> entry : domainHistory.entrySet()) {
            String domain = entry.getKey();
            DomainExperience experience = entry.getValue();

            double specialtyScore = calculationEngine.calculateSpecialtyScore(
                experience.getHistoricalDepth(),
                experience.getExpertiseLevel(),
                getEngagementConsistency(domain)
            );

            specialtyScores.put(domain, specialtyScore);
        }

        return specialtyScores.entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey)
            .orElse("GENERALIST");
    }

    public SpecialtyProfile generateSpecialtyProfile() {
        Map<String, SpecialtyLevel> domainLevels = domainMetrics.entrySet().stream()
            .collect(Collectors.toMap(
                Map.Entry::getKey,
                entry -> calculateSpecialtyLevel(entry.getValue())
            ));

        String primarySpecialty = findPrimarySpecialty(domainLevels);
        List<String> secondarySpecialties = findSecondarySpecialties(domainLevels);

        return new SpecialtyProfile(
            agentId,
            primarySpecialty,
            secondarySpecialties,
            domainLevels,
            calculateOverallExpertiseDepth()
        );
    }

    private double getEngagementConsistency(String domain) {
        DomainEngagementMetrics metrics = domainMetrics.get(domain);
        if (metrics == null) return 0.0;

        return metrics.calculateConsistencyScore();
    }

    private void checkMilestones(String domain, DomainEngagementMetrics metrics) {
        SpecialtyLevel currentLevel = calculateSpecialtyLevel(metrics);
        SpecialtyLevel previousLevel = getPreviousLevel(domain);

        if (currentLevel.ordinal() > previousLevel.ordinal()) {
            SpecialtyMilestone milestone = new SpecialtyMilestone(
                domain,
                currentLevel,
                LocalDateTime.now(),
                metrics.getEngagementDuration(),
                metrics.getTotalContributions()
            );

            milestones.add(milestone);
        }
    }

    private SpecialtyLevel calculateSpecialtyLevel(DomainEngagementMetrics metrics) {
        long engagementDays = metrics.getEngagementDuration().toDays();
        double expertiseScore = metrics.getExpertiseScore();
        int contributions = metrics.getTotalContributions();

        if (engagementDays >= 365 && expertiseScore >= 0.9 && contributions >= 100) {
            return SpecialtyLevel.MASTER;
        } else if (engagementDays >= 180 && expertiseScore >= 0.8 && contributions >= 50) {
            return SpecialtyLevel.EXPERT;
        } else if (engagementDays >= 90 && expertiseScore >= 0.7 && contributions >= 25) {
            return SpecialtyLevel.SPECIALIST;
        } else if (engagementDays >= 30 && expertiseScore >= 0.5 && contributions >= 10) {
            return SpecialtyLevel.PRACTITIONER;
        } else {
            return SpecialtyLevel.NOVICE;
        }
    }

    private SpecialtyLevel getPreviousLevel(String domain) {
        return milestones.stream()
            .filter(m -> m.getDomain().equals(domain))
            .map(SpecialtyMilestone::getLevel)
            .max(Comparator.comparing(Enum::ordinal))
            .orElse(SpecialtyLevel.NOVICE);
    }

    private String findPrimarySpecialty(Map<String, SpecialtyLevel> domainLevels) {
        return domainLevels.entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey)
            .orElse("GENERALIST");
    }

    private List<String> findSecondarySpecialties(Map<String, SpecialtyLevel> domainLevels) {
        return domainLevels.entrySet().stream()
            .filter(entry -> entry.getValue().ordinal() >= SpecialtyLevel.SPECIALIST.ordinal())
            .map(Map.Entry::getKey)
            .collect(Collectors.toList());
    }

    private double calculateOverallExpertiseDepth() {
        return domainMetrics.values().stream()
            .mapToDouble(DomainEngagementMetrics::getExpertiseScore)
            .average()
            .orElse(0.0);
    }

    // Supporting classes
    private static class DomainEngagementMetrics {
        private final String domain;
        private Duration totalEngagement;
        private double cumulativeExpertise;
        private int contributionCount;
        private LocalDateTime firstEngagement;
        private LocalDateTime lastEngagement;
        private List<Double> recentScores;

        public DomainEngagementMetrics(String domain) {
            this.domain = domain;
            this.totalEngagement = Duration.ZERO;
            this.cumulativeExpertise = 0.0;
            this.contributionCount = 0;
            this.recentScores = new ArrayList<>();
        }

        public void updateFromExperience(DomainExperience experience) {
            if (firstEngagement == null) {
                firstEngagement = LocalDateTime.now();
            }
            lastEngagement = LocalDateTime.now();

            totalEngagement = Duration.between(firstEngagement, lastEngagement);
            cumulativeExpertise += experience.getExpertiseLevel();
            contributionCount++;

            // Track recent performance for consistency calculation
            recentScores.add(experience.getExpertiseLevel());
            if (recentScores.size() > 10) {
                recentScores.remove(0);
            }
        }

        public double calculateConsistencyScore() {
            if (recentScores.size() < 3) return 0.5;

            double average = recentScores.stream().mapToDouble(Double::doubleValue).average().orElse(0.0);
            double variance = recentScores.stream()
                .mapToDouble(score -> Math.pow(score - average, 2))
                .average().orElse(0.0);

            return Math.max(0.0, 1.0 - Math.sqrt(variance));
        }

        public Duration getEngagementDuration() { return totalEngagement; }
        public double getExpertiseScore() { 
            return contributionCount > 0 ? cumulativeExpertise / contributionCount : 0.0; 
        }
        public int getTotalContributions() { return contributionCount; }
    }

    private static class SpecialtyCalculationEngine {
        public double calculateSpecialtyScore(long historicalDepth, double expertiseLevel, 
                                            double consistency) {
            // Weight factors: 40% historical depth, 35% expertise, 25% consistency
            double depthScore = Math.min(1.0, historicalDepth / (365.0 * 24 * 60 * 60 * 1000)); // Max 1 year
            return (depthScore * 0.4) + (expertiseLevel * 0.35) + (consistency * 0.25);
        }
    }

    public static class SpecialtyProfile {
        private final String agentId;
        private final String primarySpecialty;
        private final List<String> secondarySpecialties;
        private final Map<String, SpecialtyLevel> domainLevels;
        private final double overallExpertiseDepth;

        public SpecialtyProfile(String agentId, String primarySpecialty, 
                              List<String> secondarySpecialties,
                              Map<String, SpecialtyLevel> domainLevels,
                              double overallExpertiseDepth) {
            this.agentId = agentId;
            this.primarySpecialty = primarySpecialty;
            this.secondarySpecialties = new ArrayList<>(secondarySpecialties);
            this.domainLevels = new HashMap<>(domainLevels);
