 agentId, request.getTargetDomain(), request.getDuration(), 
request.getLearningObjectives()
 );

// Update agent assignment
 updateAgentAssignment(agentId, assignment);

// Record in administrative history
 recordRotationalAssignment(agentId, assignment);

