 private final ScheduledExecutorService scheduler;
 private final RotationalPolicyEngine policyEngine;

public RotationalDevelopmentManager(TrustManager trustManager, 
MemoryManager memoryManager, EventBus eventBus) {
 this.trustManager = trustManager;
 this.memoryManager = memoryManager;
 this.eventBus = eventBus;
 this.activePrograms = new ConcurrentHashMap<>();
 this.agentAssignmentHistory = new ConcurrentHashMap<>();
 this.scheduler = Executors.newScheduledThreadPool(2);
 this.policyEngine = new RotationalPolicyEngine();

initializePrograms();
