public RotationalEligibility assessEligibility(String agentId) {
 // Get agent's current specialty depth
 List<RotationalAssignment> history = agentAssignmentHistory.getOrDefault(
 agentId, Collections.emptyList()
 );

// Calculate specialty strength
 Map<String, Long> domainEngagement = calculateDomainEngagement(agentId);
 String primarySpecialty = findPrimarySpecialty(domainEngagement);
 long specialtyDepth = domainEngagement.getOrDefault(primarySpecialty, 0L);

// Apply policy rules
 RotationalPolicy policy = policyEngine.getPolicy(agentId);
 return policy.assessEligibility(specialtyDepth, history);
 }

public RotationalAssignment createAssignment(String agentId, String targetDomain, 
Duration duration, List<String> objectives) {
 String currentSpecialty = getCurrentSpecialty(agentId);

RotationalAssignment assignment = new RotationalAssignment(
 generateAssignmentId(),
