 targetDomain,
 duration,
 objectives,
 LocalDateTime.now()
 );

// Record assignment
 agentAssignmentHistory.computeIfAbsent(agentId, k -> new CopyOnWriteArrayList<>())
 .add(assignment);

// Schedule completion tracking
 scheduler.schedule(() -> completeAssignment(assignment), 
duration.toMillis(), TimeUnit.MILLISECONDS);

return assignment;
