evaluation.getKnowledgeGain() + 
evaluation.getCollaborationScore()) / 3.0 * 0.1;

trustManager.updateAgentTrust(assignment.getAgentId(), trustImpact, 
"Rotational assignment completion");
 }

private String generateAssignmentId() {
 return "ROT_" + System.currentTimeMillis() + "_" + 
ThreadLocalRandom.current().nextInt(1000, 9999);
 }

