async function generateEvolutionReport(chapterGid) {
  const versions = await storage.query({
    filter: { 'metadata.asana_task_gid': chapterGid },
    sort: { 'metadata.version_number': 1 }
  });

  const report = {
    chapter: versions[0].metadata.chapter_title,
    total_versions: versions.length,
    total_revisions: versions.length - 1,
    timeline: versions.map(v => ({
      version: v.metadata.version_number,
      date: v.metadata.created_at,
      author: v.metadata.created_by,
      stage: v.metadata.processing_stage,
      change: v.metadata.change_summary,
      qa_score: v.metadata.qa_scores.overall
    })),
    metrics: {
      initial_word_count: versions[0].metadata.word_count,
      final_word_count: versions[versions.length - 1].metadata.word_count,
      word_count_delta: versions[versions.length - 1].metadata.word_count - versions[0].metadata.word_count,

      initial_qa_score: versions[0].metadata.qa_scores.overall || 'N/A',
      final_qa_score: versions[versions.length - 1].metadata.qa_scores.overall,
      score_improvement: (versions[versions.length - 1].metadata.qa_scores.overall || 0) - (versions[0].metadata.qa_scores.overall || 0),

      total_reviewers: [...new Set(versions.map(v => v.metadata.reviewer).filter(Boolean))].length,
      total_days: calculateDaysBetween(versions[0].metadata.created_at, versions[versions.length - 1].metadata.created_at)
    },
    reviewers: versions
