**Report 3: Book-Level Quality Dashboard**
```javascript
async function generateBookQualityDashboard(bookId) {
  const allVersions = await storage.query({
    filter: { 'metadata.book_id': bookId }
  });

  // Get latest version of each chapter
  const latestVersions = {};
  for (const v of allVersions) {
    const chNum = v.metadata.chapter_number;
    if (!latestVersions[chNum] || v.metadata.version_number > latestVersions[chNum].metadata.version_number) {
      latestVersions[chNum] = v;
    }
  }

  const chapters = Object.values(latestVersions);

  const dashboard = {
    book_id: bookId,
    total_chapters: chapters.length,
    total_versions: allVersions.length,
    avg_revisions_per_chapter: (allVersions.length / chapters.length).toFixed(1),

    completion_status: {
      initial_draft: chapters.filter(c => c.metadata.processing_stage === 'initial_draft').length,
      dev_edit: chapters.filter(c => c.metadata.processing_stage.includes('dev_edit')).length,
      line_edit: chapters.filter(c => c.metadata.processing_stage.includes('line_edit')).length,
      copy_edit: chapters.filter(c => c.metadata.processing_stage.includes('copy_edit')).length,
      final_approved: chapters.filter(c => c.metadata.approval_status === 'approved_for_next_stage').length
    },

    quality_metrics: {
      avg_overall_score: calculateAvg(chapters.map(c => c.metadata.qa_scores.overall)),
      avg_plot_score: calculateAvg(chapters.map(c => c.metadata.qa_scores.plot_causality)),
      avg_character_score: calculateAvg(chapters.map(c => c.metadata.qa_scores.character_arc)),
      avg_pacing_score: calculateAvg(chapters.map(c => c.metadata.qa_scores.pacing)),
      avg_thematic_score: calculateAvg(chapters.map(c => c.metadata.qa_scores.thematic)),
      avg_voice_score: calculateAvg(chapters.map(c => c.metadata.qa_scores.voice_consistency))
    },

    content_metrics: {
      total_word_count: chapters.reduce((sum, c) => sum + c.metadata.word_count, 0),
      avg_chapter_length: calculateAvg(chapters.map(c => c.metadata.word_count)),
      total_scenes: chapters.reduce((sum, c) => sum + (c.metadata.scene_count || 0), 0)
    },

    timeline: {
      first_draft_date: allVersions.reduce((earliest, v) => 
        v.metadata.created_at < earliest ? v.metadata.created_at : earliest,
        allVersions[0].metadata.created_at
      ),
      latest_update: allVersions.reduce((latest, v) =>
        v.metadata.created_at > latest ? v.metadata.created_at : latest,
        allVersions[0].metadata.created_at
      ),
      days_in_progress: calculateDaysBetween(/* first to latest */)
    },

    bottlenecks: identifyBottlenecks(chapters),
    top_issues: identifyTopIssues(allVersions)
  };

  return dashboard;
}
