async function exportAuditTrail(bookId, format = 'json') {
  const allData = {
    book_metadata: await getBookMetadata(bookId),
    chapters: [],
    timeline: [],
    quality_evolution: [],
    reviewers: []
  };

  // Get all chapters
  const chapters = await getChaptersForBook(bookId);

  for (const chapter of chapters) {
    // Get all versions
    const versions = await storage.query({
      filter: { 'metadata.asana_task_gid': chapter.gid },
      sort: { 'metadata.version_number': 1 }
    });

    allData.chapters.push({
      chapter_number: chapter.custom_fields.chapter_number,
      chapter_title: chapter.name,
      versions: versions.map(v => ({
        version: v.metadata.version_number,
        date: v.metadata.created_at,
        author: v.metadata.created_by,
        reviewer: v.metadata.reviewer,
        stage: v.metadata.processing_stage,
        change_summary: v.metadata.change_summary,
        word_count: v.metadata.word_count,
        qa_scores: v.metadata.qa_scores,
        // Optionally include full content
        content: format === 'full' ? v.content : undefined
      }))
    });
  }

  // Generate timeline
  allData.timeline = generateTimeline(allData.chapters);

  // Quality evolution
  allData.quality_evolution = generateQualityEvolution(allData.chapters);

  // Reviewer stats
  allData.reviewers = generateReviewerStats(allData.chapters);

  // Export in requested format
  if (format === 'json') {
    return JSON.stringify(allData, null, 2);
  } else if (format === 'csv') {
    return convertToCSV(allData);
  } else if (format === 'pdf') {
    return generatePDFReport(allData);
  }
}
```

