## PART 3: REINFORCEMENT LOOP ARCHITECTURE

### 3.1 THE ITERATIVE IMPROVEMENT CYCLE

**Core Principle**: Each chapter goes through multiple revision cycles until it meets quality thresholds.

```
REINFORCEMENT LOOP:
v1: Initial Draft (baseline)
 â†“ QA Eval â†’ scores below threshold
 â†“
v2: First Revision (address dev edit issues)
 â†“ Re-Eval â†’ some scores improved, others still low
 â†“
v3: Second Revision (focused on remaining issues)
 â†“ Re-Eval â†’ most scores above threshold, pacing still low
 â†“
v4: Pacing-Focused Revision
 â†“ Re-Eval â†’ all scores above threshold!
 â†“
APPROVED â†’ Move to next stage (Line Edit)
 â†“
v5: Line Edit Pass
 â†“ Re-Eval â†’ clarity improved, new issues found
 â†“
v6: Line Edit Refinement
 â†“ Re-Eval â†’ all scores excellent
 â†“
FINAL APPROVAL â†’ Move to Copy Edit
```

### 3.2 REINFORCEMENT LOGIC IN n8n

```javascript
// Core reinforcement function
async function reinforcementLoop(taskGid) {

// 1. Get current state
 const task = await asana.tasks.getTask(taskGid, {
 opt_fields: 'custom_fields,description,name'
 });

const currentVersion = task.custom_fields.current_version || 0;
 const qaScores = extractQAScores(task.custom_fields);

// 2. Determine if meets thresholds
 const thresholds = {
 initial_draft: { overall: 70 },
 post_dev_edit: { overall: 80, each_dimension: 75 },
 post_line_edit: { overall: 85, each_dimension: 80 },
 final: { overall: 90, each_dimension: 85 }
 };

const currentStage = task.custom_fields.writing_status;
 const currentThreshold = thresholds[currentStage];

const meetsThreshold = evaluateThreshold(qaScores, currentThreshold);

// 3. Decision tree
 if (meetsThreshold) {
 // PASS: Move to next stage
 await progressToNextStage(task);

// Create storage snapshot for this milestone
 await createStorageSnapshot(task, {
 change_type: 'stage_progression',
 change_summary: `Passed ${currentStage} threshold`,
 approval_status: 'approved_for_next_stage'
 });

} else {
 // FAIL: Needs revision
 const lowDimensions = identifyLowDimensions(qaScores, currentThreshold);

// Create revision task
 await createRevisionTask(task, {
 focus_areas: lowDimensions,
 iteration: currentVersion + 1,
 target_scores: currentThreshold
 });

// Update tracking
 await asana.tasks.update(taskGid, {
 custom_fields: {
 'Revision_Count': (task.custom_fields.revision_count || 0) + 1,
 'Requires_Revision': true,
 'Focus_Areas': lowDimensions.join(', ')
 }
 });
 }

// 4. Track in Notion
 await notion.updateReinforcementLog({
 chapter: task.name,
 version: currentVersion,
 stage: currentStage,
 scores: qaScores,
 outcome: meetsThreshold ? 'PASS' : 'REVISE',
 next_action: meetsThreshold ? 'Progress' : `Revise: ${lowDimensions.join(', ')}`
 });
}
// Helper: Evaluate against threshold
function evaluateThreshold(scores, threshold) {
 // Check overall
 if (scores.overall < threshold.overall) {
 return false;
 }

// Check each dimension (if required)
 if (threshold.each_dimension) {
 const dimensions = ['plot_causality', 'character_arc', 'pacing', 'thematic', 'voice_consistency'];
 for (const dim of dimensions) {
 if (scores[dim] < threshold.each_dimension) {
 return false;
 }
 }
 }

return true;
}
// Helper: Identify low dimensions
function identifyLowDimensions(scores, threshold) {
 const low = [];
 const dimensions = ['plot_causality', 'character_arc', 'pacing', 'thematic', 'voice_consistency'];

for (const dim of dimensions) {
 if (scores[dim] < (threshold.each_dimension || threshold.overall)) {
 low.push(dim);
 }
 }

return low;
}
// Helper: Progress to next stage
async function progressToNextStage(task) {
 const stageProgression = {
 'initial_draft': 'ready_for_dev_edit',
 'ready_for_dev_edit': 'in_dev_edit',
 'in_dev_edit': 'dev_edit_complete',
 'dev_edit_complete': 'ready_for_line_edit',
 'ready_for_line_edit': 'in_line_edit',
 'in_line_edit': 'line_edit_complete',
 'line_edit_complete': 'ready_for_copy_edit',
 'ready_for_copy_edit': 'in_copy_edit',
 'in_copy_edit': 'copy_edit_complete',
 'copy_edit_complete': 'final_approved'
 };

const currentStage = task.custom_fields.writing_status;
 const nextStage = stageProgression[currentStage];

if (!nextStage) {
 throw new Error(`No next stage defined for: ${currentStage}`);
 }

await asana.tasks.update(task.gid, {
 custom_fields: {
 'Writing_Status': nextStage,
 'Stage_Progress_Date': new Date().toISOString(),
 'Requires_Revision': false
 }
 });

// Move to appropriate section in Asana
 const sectionMap = {
 'ready_for_dev_edit': 'Dev Edit Queue',
 'ready_for_line_edit': 'Line Edit Queue',
 'ready_for_copy_edit': 'Copy Edit Queue',
 'final_approved': 'Completed'
 };

if (sectionMap[nextStage]) {
 const sections = await asana.sections.findByProject(task.projects[0].gid);
 const targetSection = sections.find(s => s.name === sectionMap[nextStage]);

if (targetSection) {
 await asana.sections.addTask(targetSection.gid, { task: task.gid });
 }
 }
}
```

### 3.3 REVISION TASK CREATION

```javascript
async function createRevisionTask(task, options) {
 const { focus_areas, iteration, target_scores } = options;

// Create subtask for revision
 const revisionTask = await asana.tasks.create({
 name: `Revision ${iteration}: ${focus_areas.join(', ')}`,
 parent: task.gid,
 notes: generateRevisionGuidance(task, focus_areas, target_scores),
 assignee: task.assignee,
 due_on: calculateRevisionDeadline(task)
 });

// Add to expert review queue in Notion if needed
 if (iteration > 2) {
 // After 2 iterations, escalate to expert
 await notion.createExpertReviewTask({
 title: `${task.name} - Iteration ${iteration}`,
 priority: 'high',
 context: {
 asana_task: task.permalink_url,
 focus_areas: focus_areas,
 current_scores: extractQAScores(task.custom_fields),
 target_scores: target_scores,
 note: `Multiple revisions needed. Expert guidance required.`
 }
 });
 }

return revisionTask;
}
function generateRevisionGuidance(task, focus_areas, target_scores) {
 let guidance = `**Revision Focus Areas:**\n\n`;

for (const area of focus_areas) {
 const currentScore = task.custom_fields[`${area}_score`];
 const targetScore = target_scores.each_dimension || target_scores.overall;
 const gap = targetScore - currentScore;

guidance += `**${area}** (Current: ${currentScore}, Target: ${targetScore}, Gap: ${gap})\n`;
 guidance += getSpecificGuidance(area, gap) + '\n\n';
 }

return guidance;
}
function getSpecificGuidance(dimension, gap) {
 const guidance = {
 plot_causality: {
 small: '- Review cause-effect chains\n- Ensure events logically follow from previous events',
 large: '- Major plot hole detected\n- Consider restructuring key events\n- Expert review recommended'
 },
 pacing: {
 small: '- Adjust scene lengths\n- Add/remove transitional paragraphs',
 large: '- Significant pacing issues\n- Restructure chapter into different scenes\n- Consider changing POV or timeline'
 },
 character_arc: {
 small: '- Add character reaction beats\n- Strengthen motivation',
 large: '- Character behavior inconsistent\n- Revisit character arc design\n- Expert consultation needed'
 }
 // ... etc for all dimensions
 };

const category = gap < 10 ? 'small' : 'large';
 return guidance[dimension]?.[category] || 'See expert notes for guidance';
}
```

