### 3.5 AUTOMATIC ITERATION LIMITS

```javascript
// Prevent infinite loops
async function checkIterationLimit(task) {
 const revisionCount = task.custom_fields.revision_count || 0;
 const stage = task.custom_fields.writing_status;

const limits = {
 'initial_draft': 3,
 'dev_edit': 5,
 'line_edit': 3,
 'copy_edit': 2
 };

const limit = limits[stage] || 5;

if (revisionCount >= limit) {
 // Escalate to human decision
 await notion.createAlert({
 type: 'iteration_limit_exceeded',
 chapter: task.name,
 stage: stage,
 iterations: revisionCount,
 limit: limit,
 message: `Chapter has exceeded ${limit} iterations at ${stage} stage. Manual intervention required.`,
 actions: [
 'Approve and move forward (accept current quality)',
 'Assign to expert for deep review',
 'Mark for major restructure',
 'Extend iteration limit by 3'
 ]
 });

// Pause automatic processing
 await asana.tasks.update(task.gid, {
 custom_fields: {
 'Requires_Manual_Review': true,
 'Processing_Paused': true
 }
 });

return false; // Don't continue automatic loop
 }

return true; // Can continue
}
```

