// Quality evolution
 allData.quality_evolution = generateQualityEvolution(allData.chapters);

// Reviewer stats
 allData.reviewers = generateReviewerStats(allData.chapters);

// Export in requested format
 if (format === 'json') {
 return JSON.stringify(allData, null, 2);
 } else if (format === 'csv') {
 return convertToCSV(allData);
