        ":contentReference[oaicite:14]{index=14}"
      ]
    },
    {
      "name": "Webhook",
      "category": "Core",
      "purpose": "Creates a unique URL that allows external services to send data into n8n. Acts like a digital mailbox for building reactive automations",
      "key_operations": [
        "Generate webhook URL",
        "Receive data from external service"
      ],
      "data_model": "When a request is received, the node outputs an item whose `json` property contains the requestâ€™s query parameters, headers and body; binary uploads appear under `binary`.",
      "sources": [
        ":contentReference[oaicite:15]{index=15}"
      ]
    },
    {
      "name": "Respond to Webhook",
      "category": "Core",
      "purpose": "Sends an immediate confirmation back to the sender of a webhook. This prevents duplicate retries by confirming receipt of the data",
      "key_operations": [
        "Send HTTP response to external service"
      ],
      "data_model": "Returns an array containing the response data. Depending on configuration, it can send JSON, binary data or no body.",
      "sources": [
        ":contentReference[oaicite:16]{index=16}"
      ]
    },
    {
      "name": "Google Sheets",
      "category": "Action in an app",
      "purpose": "Automates tasks in Google Sheets and integrates Sheets with other applications. Supports creating, updating, deleting, appending, removing and retrieving spreadsheets and rows",
      "key_operations": [
        "Create spreadsheet",
        "Append or update row",
        "Clear sheet",
        "Create or delete sheet",
        "Get rows",
        "Update row"
      ],
      "data_model": "Consumes items containing row data and outputs items representing created, updated or retrieved rows. Each itemâ€™s `json` contains the row data returned by Google Sheets.",
      "sources": [
        ":contentReference[oaicite:17]{index=17}"
      ]
    },
    {
      "name": "Gmail",
      "category": "Action in an app",
      "purpose": "Automates Gmail tasks and integrates Gmail with other applications. Supports creating, updating, deleting and retrieving drafts, messages, labels and threads",
      "key_operations": [
        "Create/delete/get drafts",
        "Create/delete/get labels",
        "Add/remove label to message",
        "Send or reply to message",
        "Mark message read or unread",
        "Get thread"
      ],
      "data_model": "Processes items representing email actions and returns items containing Gmail API responses such as message IDs, content or metadata.",
      "sources": [
        ":contentReference[oaicite:18]{index=18}"
      ]
    },
    {
      "name": "Slack",
      "category": "Action in an app",
      "purpose": "Automates Slack tasks and integrates Slack with other applications. Supports creating, archiving and closing channels, retrieving users and files and sending or deleting messages",
      "key_operations": [
        "Create/delete/archive channels",
        "Send message",
        "Send and wait for approval",
        "Get or delete messages",
        "Upload file",
        "Get users or files",
        "Manage reactions"
      ],
      "data_model": "For each input item, performs the Slack operation and outputs items containing Slack API responses (for example, message or channel details).",
      "sources": [
        ":contentReference[oaicite:19]{index=19}"
      ]
    },
    {
      "name": "Wait",
      "category": "Human in the loop",
      "purpose": "Pauses the workflow and resumes it later when a condition is met, such as after a time interval, at a specified time, on a webhook call or upon form submission",
      "key_operations": [
        "Wait after time interval",
        "Wait until specified time",
        "Wait on webhook call",
        "Wait on form submitted"
      ],
      "data_model": "Offloads execution data to the database while waiting. When the resume condition occurs, the node reloads the stored items and continues processing with the same items.",
      "sources": [
        ":contentReference[oaicite:20]{index=20}"
      ]
    },
    {
      "name": "Human Approval (Human in the Loop)",
      "category": "Human in the loop",
      "purpose": "Inserts manual approval steps into workflows. Allows a human to approve, reject or adjust actions before they proceed; provides context, flexible notifications and audit trails",
      "key_operations": [
        "Send approval request via Slack, Discord, Google, WhatsApp or webhook",
        "Provide context for decisions",
        "Maintain audit trail"
      ],
      "data_model": "Typically built with a Wait node combined with messaging nodes. The Wait node holds execution until a response arrives; once approved, the workflow resumes with the same items.",
      "sources": [
        ":contentReference[oaicite:21]{index=21}"
      ]
    },
    {
      "name": "Basic LLM Chain",
      "category": "AI",
      "purpose": "Sets a prompt for a language model and optionally parses the response. Itâ€™s used for single-step AI tasks such as sentiment analysis, data extraction or text classification",
      "key_operations": [
        "Construct prompt manually or from previous node",
        "Configure output parser (auto-fixing, item list or structured)",
        "Send request to language model",
        "Receive and parse response"
      ],
      "data_model": "Receives items with a `json` field containing the input text or chat messages. Returns items with the modelâ€™s response in the `json` field; optional output parsers structure the response.",
      "sources": [
        ":contentReference[oaicite:22]{index=22}",
        ":contentReference[oaicite:23]{index=23}"
      ]
    },
    {
      "name": "AI Agent",
      "category": "AI",
      "purpose": "Manages multi-step AI workflows by reasoning and calling tools. An agent runs multiple times during execution: it may perform initial setup, call a tool (such as another node) and then evaluate the toolâ€™s response before responding to the user",
      "key_operations": [
        "Receive user query",
        "Plan steps and select tools",
        "Call appropriate nodes (tools)",
        "Evaluate tool responses",
        "Return final answer"
      ],
      "data_model": "Receives items with user input; the agent may produce intermediate items while planning and calling tools. The final output item contains the AI response and any relevant metadata.",
      "sources": [
        ":contentReference[oaicite:24]{index=24}",
        ":contentReference[oaicite:25]{index=25}"
      ]
    },

    // --- Additional nodes for multi-agent collaborative book-writing system ---

    {
      "name": "Chat Trigger",
      "category": "Trigger",
      "purpose": "Starts a workflow when a user sends a message into a chat interface connected to n8n (for example, a chat widget, Slack app or custom frontend). Ideal entrypoint for conversational multi-agent book-writing assistants.",
      "key_operations": [
        "Receive chat message",
        "Populate chatInput field for downstream AI nodes"
      ],
      "data_model": "Produces items where `json.chatInput` contains the userâ€™s message plus optional metadata (user id, channel id, timestamp). Designed to feed directly into Basic LLM Chain or AI Agent nodes.",
      "sources": []
    },
    {
      "name": "Form Trigger",
      "category": "Trigger",
      "purpose": "Starts a workflow when a structured form is submitted (e.g., chapter review form, editorial checklist). Useful for collecting human feedback on drafts.",
      "key_operations": [
        "Provide form to reviewer",
        "Receive submitted fields as structured JSON"
      ],
      "data_model": "Outputs one item per submission with `json` containing each form field (such as rating, comments, sectionId). Integrates naturally with Wait/Human Approval flows.",
      "sources": []
    },
    {
      "name": "Execute Workflow",
      "category": "Flow",
      "purpose": "Calls another workflow as a sub-workflow. Useful for modularizing book-writing tasks such as chapter outlining, consistency checking or reference cleanup.",
      "key_operations": [
        "Call sub-workflow with current items",
        "Receive processed items from sub-workflow"
      ],
      "data_model": "Takes the incoming items and passes them into the target workflow; the called workflow outputs items that become this nodeâ€™s output. Item structure (`json`/`binary`) is preserved across workflows.",
      "sources": []
    },
    {
      "name": "Item Lists",
      "category": "Data Transformation",
      "purpose": "Performs list-level operations like sorting, filtering, limiting, or combining arrays of items. Useful for handling chapter lists, revision queues or editorial task backlogs.",
      "key_operations": [
        "Sort items by field",
        "Filter items by condition",
        "Limit or slice item ranges",
        "Aggregate values (min/max/avg/count)"
      ],
      "data_model": "Operates on the array of items as a whole and returns a transformed array, preserving item `json` structure but potentially changing which items are present and their order.",
      "sources": []
    },
    {
      "name": "Split In Batches",
      "category": "Flow",
      "purpose": "Processes large sets of items in batches. Critical for long manuscripts where you need to process chapters or sections in chunks to respect model token limits or API rate limits.",
      "key_operations": [
        "Define batch size",
        "Loop through items batch by batch"
      ],
      "data_model": "Accepts an array of items and exposes them to downstream nodes in fixed-size batches while preserving each itemâ€™s `json`/`binary` data. After each batch completes, control returns to this node for the next batch.",
      "sources": []
    },
    {
      "name": "Notion",
      "category": "Action in an app",
      "purpose": "Stores and retrieves structured book assets in Notion databases (chapters, character sheets, research notes) and pages. Works well as a collaborative knowledge base for multi-agent and human co-authors.",
      "key_operations": [
        "Create/update/delete pages",
        "Query databases (filter/sort)",
        "Append blocks to existing pages"
      ],
      "data_model": "Consumes items whose `json` contains Notion page or database payloads; outputs items with Notion API responses, typically including IDs, properties and block content.",
      "sources": []
    },
    {
      "name": "Google Docs",
      "category": "Action in an app",
      "purpose": "Manages long-form documents stored in Google Docsâ€”chapters, outlines, feedback docs. Suitable for round-tripping text between AI agents and human editors.",
      "key_operations": [
        "Create document",
        "Get document content",
        "Update document text or insert content at positions"
      ],
      "data_model": "Inputs items with document IDs or content snippets; outputs items whose `json` includes document metadata and content fragments, which can then be passed to LLM nodes for editing or summarization.",
      "sources": []
    },
    {
      "name": "Google Drive",
      "category": "Action in an app",
      "purpose": "Stores binary assets related to the book (figures, reference PDFs, exported manuscript versions).",
      "key_operations": [
        "Upload file",
        "Download file",
        "List files in folder"
      ],
      "data_model": "Uses `binary` for file contents (e.g. exported PDF/Docx) and `json` for metadata (fileId, name, mimeType, parents). Downstream nodes can read either metadata or binary as needed.",
      "sources": []
    },
    {
      "name": "Discord",
      "category": "Action in an app / Human in the loop",
      "purpose": "Sends messages to Discord channels or DMs to notify human reviewers, capture inline feedback or route drafts to specific review channels.",
      "key_operations": [
        "Send message to channel",
        "Send DM to reviewer",
        "Post links to drafts and review tasks"
      ],
      "data_model": "For each input item, posts a message based on fields in `json` (content, embeds, channelId, mentioned users) and outputs items containing Discord API responses (message IDs, timestamps). Can be paired with Wait/Webhook to capture replies via bots.",
      "sources": []
    },
    {
      "name": "Read Binary File",
      "category": "Core",
      "purpose": "Reads local files (Markdown, PDF, Word) from disk into `binary` data so they can be processed by AI or stored in cloud drives.",
      "key_operations": [
        "Read file from path",
        "Expose contents as binary field"
      ],
      "data_model": "Creates items whose `binary` field contains the file data and whose `json` may include path/filename metadata. Often followed by a text-extraction or AI node.",
      "sources": []
    },
    {
      "name": "Write Binary File",
      "category": "Core",
      "purpose": "Writes binary data from items back to disk, for example exporting AI-edited manuscripts as Markdown or DOCX.",
      "key_operations": [
        "Write binary data to path",
        "Control overwrite behavior"
      ],
      "data_model": "Consumes items with `binary` data (e.g. `binary.data` or `binary.file`) and writes them to files without changing the item structure; the node outputs the same items with possibly updated `json` metadata (file path, success flag).",
      "sources": []
    },
    {
      "name": "Postgres",
      "category": "Action in an app",
      "purpose": "Stores structured metadata for the book project: chapter status, agent assignments, review logs, coherence metrics.",
      "key_operations": [
        "Insert row",
        "Update row",
        "Select/query rows",
        "Delete row"
      ],
      "data_model": "Maps item `json` fields to table columns when writing and returns rows as `json` objects when reading. Ideal for keeping a durable state machine for multi-agent orchestration over long projects.",
      "sources": []
    },
    {
      "name": "OpenAI Chat Model",
      "category": "AI",
      "purpose": "Runs chat-style large-language-model calls (e.g., drafting paragraphs, rewriting sections, answering questions about the manuscript). Typically used inside an agent toolchain.",
      "key_operations": [
        "Generate text from system/user messages",
        "Stream or batch responses",
        "Condition on previous conversation history"
      ],
      "data_model": "Consumes items where `json` contains chat messages and model parameters; outputs items with `json` fields such as `response`, `choices`, token usage and optional tool call metadata.",
      "sources": []
    },
    {
      "name": "Question & Answer Chain",
      "category": "AI",
      "purpose": "Provides retrieval-augmented Q&A over source documents (e.g., the current manuscript, research corpus, style guide). Useful for agents checking facts or maintaining continuity across chapters.",
      "key_operations": [
        "Accept user question",
        "Retrieve relevant context from connected tools",
        "Generate grounded answer"
      ],
      "data_model": "Input item `json` includes a `question` field (and optionally `context` identifiers); output `json` includes `answer`, `sources` and sometimes intermediate reasoning traces. Works well as a tool inside an AI Agent.",
      "sources": []
    }
  ]
}

{
  "name": "Notion Unfurl - n8n Workflows",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "notion-unfurl",
        "responseMode": "responseNode",
        "options": {}
      },
      "id": "webhook-trigger-node",
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 2,
      "position": [
        250,
        300
      ],
      "webhookId": "notion-unfurl"
    },
    {
      "parameters": {
        "jsCode": "// Extract workflow ID from the URL Notion sends\nconst body = $input.item.json.body;\n\n// Check if this is a valid unfurl request\nif (!body || !body.url) {\n  return {\n    json: {\n      error: 'No URL provided in request'\n    }\n  };\n}\n\nconst url = body.url;\nconsole.log('Received unfurl request for URL:', url);\n\n// Extract workflow ID from URLs like:\n// https://nycsenseat.com/workflow/abc123\n// https://n8n.nycsenseat.com/workflow/abc123\nconst workflowMatch = url.match(/\\/workflow\\/([a-zA-Z0-9]+)/);\n\nif (!workflowMatch) {\n  return {\n    json: {\n      error: 'Could not extract workflow ID from URL',\n      url: url\n    }\n  };\n}\n\nconst workflowId = workflowMatch[1];\n\nreturn {\n  json: {\n    workflowId: workflowId,\n    originalUrl: url\n  }\n};"
      },
      "id": "extract-workflow-id",
      "name": "Extract Workflow ID",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        470,
        300
      ]
    },
    {
      "parameters": {
        "method": "GET",
        "url": "=https://n8n.nycsenseat.com/api/v1/workflows/{{ $json.workflowId }}",
        "authentication": "genericCredentialType",
        "genericAuthType": "httpHeaderAuth",
        "options": {}
      },
      "id": "get-workflow-details",
      "name": "Get Workflow Details",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [
        690,
        300
      ],
      "credentials": {
        "httpHeaderAuth": {
          "id": "n8n-api-key",
          "name": "n8n API Key"
        }
      },
      "notes": "IMPORTANT: You must create an HTTP Header Auth credential named 'n8n API Key' with:\n- Name: X-N8N-API-KEY\n- Value: Your n8n API key from Settings > API"
    },
    {
      "parameters": {
        "jsCode": "// Format response for Notion's unfurl API\nconst workflow = $input.item.json;\nconst originalUrl = $('Extract Workflow ID').item.json.originalUrl;\n\n// Handle error case\nif (!workflow || !workflow.id) {\n  return {\n    json: {\n      type: \"block_card\",\n      block_card: {\n        title: {\n          type: \"text\",\n          text: \"Workflow Not Found\"\n        },\n        description: {\n          type: \"text\",\n          text: \"Could not retrieve workflow details\"\n        },\n        url: originalUrl\n      }\n    }\n  };\n}\n\n// Build description with workflow metadata\nconst activeStatus = workflow.active ? 'âœ“ Active' : 'âœ— Inactive';\nconst nodeCount = workflow.nodes ? workflow.nodes.length : 0;\nconst updatedDate = workflow.updatedAt ? new Date(workflow.updatedAt).toLocaleDateString() : 'Unknown';\n\nconst description = `${activeStatus} | ${nodeCount} nodes | Updated: ${updatedDate}`;\n\n// Return Notion unfurl format\nreturn {\n  json: {\n    type: \"block_card\",\n    block_card: {\n      title: {\n        type: \"text\",\n        text: workflow.name || \"Untitled Workflow\"\n      },\n      description: {\n        type: \"text\",\n        text: description\n      },\n      url: originalUrl\n    }\n  }\n};"
      },
      "id": "format-notion-response",
      "name": "Format Notion Response",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        910,
        300
      ]
    },
    {
      "parameters": {
        "respondWith": "json",
        "responseBody": "={{ $json }}",
        "options": {}
      },
      "id": "respond-to-webhook",
      "name": "Respond to Webhook",
      "type": "n8n-nodes-base.respondToWebhook",
      "typeVersion": 1.1,
      "position": [
        1130,
        300
      ]
    }
  ],
