# PyTorch Geometric - Graph Neural Network for code
import torch
import torch_geometric as pyg
from torch_geometric.nn import GCNConv, GATConv

class CodeGraphEncoder(torch.nn.Module):
    """Neural network for code dependency graphs"""
    
    def __init__(self):
        super().__init__()
        # Graph Convolutional layers
        self.conv1 = GCNConv(in_channels=128, out_channels=256)
        self.conv2 = GCNConv(in_channels=256, out_channels=512)
        self.attention = GATConv(in_channels=512, out_channels=256)
        
    def forward(self, code_graph):
        # code_graph has nodes (classes/methods) and edges (dependencies)
        x, edge_index = code_graph.x, code_graph.edge_index
        
        # Propagate information through graph
        x = self.conv1(x, edge_index).relu()
        x = self.conv2(x, edge_index).relu()
        x = self.attention(x, edge_index)
        
        return x  # Learned code representation
```

