@app.route('/sensitivity/symmetrical', methods=['POST'])
def handle_symmetrical_analysis():
    """Processes symmetrical sensitivity analysis with a single percentage variation."""
    data = request.json
    param_id = data['param_id']
    percentage = data['values'][0]
    comparison_param = data['compareToKey']
    plot_types = []

    if data['waterfallPlot']: plot_types.append('waterfall')
    if data['barPlot']: plot_types.append('bar')
    if data['pointPlot']: plot_types.append('point')

    # Process symmetrical calculations (+/- percentage)
    results = process_symmetrical_variation(param_id, percentage, comparison_param)

    # Generate visualizations based on plot_types
    visualizations = generate_sensitivity_plots(results, plot_types)

    return jsonify({
        'results': results,
        'visualizations': visualizations
    })

@app.route('/sensitivity/multipoint', methods=['POST'])
def handle_multipoint_analysis():
    """Processes multiple point sensitivity analysis with up to six variations."""
    data = request.json
