import re
import json
from pathlib import Path

class CSSCleaner:
    def __init__(self):
        self.class_map = {}  # {class_name: {file_number: definition}}

    def extract_classes(self, content):
        # Match class definitions including nested selectors and pseudo-selectors
        pattern = r'html body (?:[^{]+?\.[\w-]+[^{]*)\{[^}]+\}'
        matches = re.finditer(pattern, content)
        classes = {}

        for match in matches:
            definition = match.group(0)
            # Extract full selector path
            selector = re.search(r'html body ([^{]+)', definition).group(1).strip()

            # Extract base class name (first class in selector)
            base_class = re.search(r'\.([^:\s]+)', selector).group(1)

            # Create a unique key that includes the full selector
            selector_key = selector.replace('html body ', '').strip()

            classes[selector_key] = {
                'base_class': base_class,
                'full_selector': selector,
                'definition': definition.strip()
            }

        return classes

    def add_to_class_map(self, file_number, classes):
        """Add classes to the class map with their full selectors"""
        for selector_key, info in classes.items():
            base_class = info['base_class']
            if base_class not in self.class_map:
                self.class_map[base_class] = {}

            if selector_key not in self.class_map[base_class]:
                self.class_map[base_class][selector_key] = {
                    'files': [],
                    'definitions': {}
                }

            self.class_map[base_class][selector_key]['files'].append(file_number)
            self.class_map[base_class][selector_key]['definitions'][str(file_number)] = info['definition']

    def scan_file(self, file_number):
        file_path = Path(f'src/L_1_HomePage{file_number}.css')
        if not file_path.exists():
            print(f"Warning: {file_path} not found")
            return

        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()

        classes = self.extract_classes(content)
        self.add_to_class_map(file_number, classes)

    def scan_all_files(self):
        for i in range(1, 7):
            self.scan_file(i)

    def find_duplicates(self):
        duplicates = {}
        by_file = {}  # Track duplicates per file
        total_duplicates = 0

        for base_class, selectors in self.class_map.items():
            for selector_key, info in selectors.items():
                if len(info['files']) > 1:
                    if base_class not in duplicates:
                        duplicates[base_class] = {}

                    duplicates[base_class][selector_key] = {
                        "files": info['files'],
                        "definitions": info['definitions']
                    }

                    # Count duplicates per file (excluding the last file)
                    sorted_files = sorted(info['files'])
                    for file_num in sorted_files[:-1]:
                        by_file[str(file_num)] = by_file.get(str(file_num), 0) + 1
                    # Add to total (excluding one original instance)
                    total_duplicates += len(info['files']) - 1

        # Create report with summary
        report = {
            "classes": duplicates,
            "summary": {
                "total_duplicates": total_duplicates,
                "unique_duplicates": sum(len(selectors) for selectors in duplicates.values()),
                "files_affected": len(by_file),
                "by_file": by_file
            }
        }

        # Write to JSON file
        with open('removed_classes.json', 'w', encoding='utf-8') as f:
            json.dump(report, f, indent=2, ensure_ascii=False)

        return report

def main():
    cleaner = CSSCleaner()
    cleaner.scan_all_files()
    report = cleaner.find_duplicates()

    # Print summary
    print("\nDuplicate Classes Summary:")
    print(f"Total duplicate instances: {report['summary']['total_duplicates']}")
    print(f"Unique duplicate classes: {report['summary']['unique_duplicates']}")
    print(f"Files affected: {report['summary']['files_affected']}")
    print("\nDuplicates by file:")
    for file_num, count in sorted(report['summary']['by_file'].items()):
        print(f"  File {file_num}: {count} duplicates")

    print("\nDetailed class breakdown:")
    for base_class, selectors in report['classes'].items():
        print(f"\nBase class: {base_class}")
        for selector, info in selectors.items():
            print(f"  Selector: {selector}")
            print(f"  Appears in files: {info['files']}")

if __name__ == "__main__":
    main()

import json
import re
from pathlib import Path

class CSSProcessor:
    def __init__(self):
        self.duplicates = {}
        self.to_remove = {}  # {file_number: [classes_to_remove]}

    def load_duplicates(self):
        with open('removed_classes.json', 'r', encoding='utf-8') as f:
            data = json.load(f)
            self.duplicates = data['classes']  # Get the classes from the new format

    def process_duplicates(self):
        """Process duplicates keeping only the last definition of each class"""
        for base_class, selectors in self.duplicates.items():
            for selector_key, info in selectors.items():
                files = sorted(map(int, info['files']))  # Convert to int for proper sorting
                # Keep only the last file's definition
                last_file = str(files[-1])

                # Mark earlier definitions for removal
                for file_num in files[:-1]:
                    file_num = str(file_num)
                    if file_num not in self.to_remove:
                        self.to_remove[file_num] = []
                    self.to_remove[file_num].append({
                        'class': base_class,
                        'selector': selector_key,
                        'definition': info['definitions'][file_num]
                    })

    def remove_from_files(self):
        """Remove overridden classes from CSS files"""
        for file_num, classes in self.to_remove.items():
            file_path = Path(f'src/L_1_HomePage{file_num}.css')
            if not file_path.exists():
                print(f"Warning: {file_path} not found")
                continue

            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()

            # Remove each class definition
            for class_info in classes:
                definition = class_info['definition']
                # Escape special characters for regex
                escaped_def = re.escape(definition)
                # Remove the definition and any following whitespace
                content = re.sub(f"{escaped_def}\\s*", '', content)

            # Write the updated content back
            with open(file_path, 'w', encoding='utf-8') as f:
                f.write(content)

    def generate_report(self):
        """Generate a report of removed classes"""
        report = {
            'removed_classes': {},
            'summary': {
                'total_removed': 0,
                'files_affected': len(self.to_remove)
            }
        }

        total_removed = 0
        for file_num, classes in self.to_remove.items():
            report['removed_classes'][f'file_{file_num}'] = {
                'count': len(classes),
                'classes': [{
                    'base_class': c['class'],
                    'full_selector': c['selector'],
                    'definition': c['definition']
                } for c in classes]
            }
            total_removed += len(classes)

        report['summary']['total_removed'] = total_removed

        # Write report
        with open('removal_report.json', 'w', encoding='utf-8') as f:
            json.dump(report, f, indent=2)

        return report

def main():
    processor = CSSProcessor()

    print("Loading duplicate classes...")
    processor.load_duplicates()

    print("\nProcessing duplicates...")
    processor.process_duplicates()

    print("\nRemoving overridden classes from files...")
    processor.remove_from_files()

    print("\nGenerating report...")
    report = processor.generate_report()

    print("\nSummary:")
    print(f"Total classes removed: {report['summary']['total_removed']}")
    print(f"Files affected: {report['summary']['files_affected']}")
    print("\nDetailed report saved to 'removal_report.json'")

if __name__ == "__main__":
    main()

const fs = require('fs');
const path = require('path');

function extractZLevels(cssContent) {
  const zLevels = {};
  const selectors = cssContent.match(/html\s+body\s+\.[\w-]+:not\(#_\):not\(#_\):not\(#_\)[^{]*\{[^}]*z-index:[^}]+\}/g) || [];

  selectors.forEach(selector => {
    const componentMatch = selector.match(/html\s+body\s+\.([\w-]+)(?=:not\(#_\))/);
    const zIndexMatch = selector.match(/z-index:\s*(\d+)/);

    if (componentMatch && zIndexMatch) {
      const component = componentMatch[1];
      const level = zIndexMatch[1];

      if (!zLevels[level]) zLevels[level] = [];
      if (!zLevels[level].includes(component)) {
        zLevels[level].push(component);
      }
    }
  });

  // Add components without explicit z-index to level 0
  const allSelectors = cssContent.match(/html\s+body\s+\.[\w-]+:not\(#_\):not\(#_\):not\(#_\)[^{]*\{[^}]+\}/g) || [];
  allSelectors.forEach(selector => {
    const componentMatch = selector.match(/html\s+body\s+\.([\w-]+)(?=:not\(#_\))/);
    if (componentMatch) {
      const component = componentMatch[1];
      if (!Object.values(zLevels).flat().includes(component)) {
        if (!zLevels['0']) zLevels['0'] = [];
        zLevels['0'].push(component);
      }
    }
  });

  return zLevels;
}

function extractFlowAndPosition(cssContent) {
  const components = {};
  const selectors = cssContent.match(/html\s+body\s+\.[\w-]+:not\(#_\):not\(#_\):not\(#_\)[^{]*\{[^}]+\}/g) || [];
  const nestedSelectors = cssContent.match(/html\s+body\s+\.[\w-]+(?:\s+\.[\w-]+)+:not\(#_\):not\(#_\):not\(#_\)[^{]*\{[^}]+\}/g) || [];
  const gridAreaSelectors = cssContent.match(/html\s+body\s+\.[\w-]+:not\(#_\):not\(#_\):not\(#_\)[^{]*\{[^}]*grid-area:[^}]+\}/g) || [];
  const gridTemplateSelectors = cssContent.match(/html\s+body\s+\.[\w-]+:not\(#_\):not\(#_\):not\(#_\)[^{]*\{[^}]*grid-template-areas:[^}]+\}/g) || [];

  // Track grid templates and areas
  const gridTemplates = {};
  gridTemplateSelectors.forEach(selector => {
    const componentMatch = selector.match(/html\s+body\s+\.([\w-]+)(?=:not\(#_\))/);
    if (componentMatch) {
      const component = componentMatch[1];
      const templateMatch = selector.match(/grid-template-areas:\s*([^;]+)/);
      if (templateMatch) {
        gridTemplates[component] = {
          areas: templateMatch[1].replace(/['"]/g, '').trim().split(/\s+/),
          components: {}
        };
      }
    }
  });

  // Map components to grid areas
  gridAreaSelectors.forEach(selector => {
    const componentMatch = selector.match(/html\s+body\s+\.([\w-]+)(?=:not\(#_\))/);
    const areaMatch = selector.match(/grid-area:\s*([^;]+)/);
    if (componentMatch && areaMatch) {
      const component = componentMatch[1];
      const area = areaMatch[1].trim();
      Object.keys(gridTemplates).forEach(template => {
        if (gridTemplates[template].areas.includes(area)) {
          gridTemplates[template].components[area] = component;
        }
      });
    }
  });

  // Process direct selectors
  selectors.forEach(selector => {
    const componentMatch = selector.match(/html\s+body\s+\.([\w-]+)(?=:not\(#_\))/);
    if (componentMatch) {
      const component = componentMatch[1];
      const styles = selector.match(/\{([^}]+)\}/)[1];

      if (!components[component]) components[component] = {};

      // Extract flow patterns
      if (styles.includes('display: flex')) {
        const flowInfo = {
          type: 'flex',
          direction: styles.includes('flex-direction: column') ? 'column' : 'row',
          distribution: {}
        };

        // Extract distribution patterns
        const justifyMatch = styles.match(/justify-content:\s*([^;]+)/);
        const alignMatch = styles.match(/align-items:\s*([^;]+)/);
        const gapMatch = styles.match(/gap:\s*([^;]+)/);

        if (justifyMatch) flowInfo.distribution.main = justifyMatch[1].replace(/\s*!important/, '');
        if (alignMatch) flowInfo.distribution.cross = alignMatch[1].replace(/\s*!important/, '');
        if (gapMatch) flowInfo.distribution.spacing = gapMatch[1].replace(/\s*!important/, '');

        components[component].flow = flowInfo;
      } else if (styles.includes('display: grid')) {
        const flowInfo = {
          type: 'grid',
          distribution: {}
        };

        // Extract grid patterns
        const templateColsMatch = styles.match(/grid-template-columns:\s*([^;]+)/);
        const templateRowsMatch = styles.match(/grid-template-rows:\s*([^;]+)/);
        const templateAreasMatch = styles.match(/grid-template-areas:\s*([^;]+)/);
        const gapMatch = styles.match(/gap:\s*([^;]+)/);

        if (templateColsMatch) flowInfo.distribution.columns = templateColsMatch[1].replace(/\s*!important/, '');
        if (templateRowsMatch) flowInfo.distribution.rows = templateRowsMatch[1].replace(/\s*!important/, '');
        if (templateAreasMatch) {
          flowInfo.distribution.areas = templateAreasMatch[1].replace(/\s*!important/, '');
          if (gridTemplates[component]) {
            flowInfo.distribution.areaMap = gridTemplates[component].components;
          }
        }
        if (gapMatch) flowInfo.distribution.spacing = gapMatch[1].replace(/\s*!important/, '');

        components[component].flow = flowInfo;
      }

      // Extract position
      if (styles.includes('position: sticky')) {
        components[component].position = 'sticky';
      } else if (styles.includes('position: fixed')) {
        components[component].position = 'fixed';
      }

      // Extract grid spans
      const gridColMatch = styles.match(/grid-column:\s*([^;]+)/);
      if (gridColMatch) components[component].span = gridColMatch[1].replace(/\s*!important/, '');
    }
  });

  // Process nested selectors for inheritance chain
  nestedSelectors.forEach(selector => {
    const componentChain = selector.match(/\.[\w-]+/g).map(s => s.slice(1));
    const styles = selector.match(/\{([^}]+)\}/)[1];

    // Build inheritance chain
    componentChain.forEach((component, index) => {
      if (!components[component]) components[component] = {};

      if (index > 0) {
        const parent = componentChain[index - 1];
        if (!components[component].inherits) {
          components[component].inherits = {
            parent,
            properties: []
          };
        }

        // Track inherited properties
        if (styles.includes('display:')) {
          components[component].inherits.properties.push('flow');
        }
        if (styles.includes('justify-content:') || styles.includes('align-items:')) {
          components[component].inherits.properties.push('distribution');
        }
        if (styles.includes('grid-area:')) {
          components[component].inherits.properties.push('area');
        }
      }
    });

    // Track affects relationships based on z-index differences
    const zIndexMatch = selector.match(/z-index:\s*(\d+)/);
    if (zIndexMatch) {
      const zLevel = parseInt(zIndexMatch[1]);
      componentChain.forEach((component, index) => {
        if (index < componentChain.length - 1) {
          const child = componentChain[index + 1];
          const childZLevel = parseInt(components[child]?.level || '0');
          if (zLevel > childZLevel) {
            if (!components[component].affects) components[component].affects = [];
            if (!components[component].affects.includes(child)) {
              components[component].affects.push(child);
            }
          }
        }
      });
    }
  });

  return components;
}

function buildComponentTree(components, zLevels) {
  // Add grid area mapping
  const gridAreas = {};
  Object.entries(components).forEach(([component, props]) => {
    if (props.flow?.type === 'grid') {
      gridAreas[component] = {
        template: props.flow.distribution,
        areas: props.flow.distribution.areaMap || {}
      };
    }
    if (props.flow?.area) {
      // Find grid parent through inheritance chain
      let currentComponent = component;
      while (currentComponent) {
        const parent = components[currentComponent]?.inherits?.parent;
        if (parent && components[parent]?.flow?.type === 'grid') {
          if (!gridAreas[parent]) {
            gridAreas[parent] = {
              template: components[parent].flow.distribution,
              areas: components[parent].flow.distribution.areaMap || {}
            };
          }
          gridAreas[parent].areas[props.flow.area] = component;
          break;
        }
        currentComponent = parent;
      }
    }
  });

  const tree = { componentTree: {}, overlayTree: {} };
  const processedComponents = new Set();

  // Find root component (L_1_HomePage or main container)
  const rootComponent = Object.values(zLevels)
    .flat()
    .find(comp => comp === 'L_1_HomePage' || comp === 'main-content');

  if (!rootComponent) {
    throw new Error('Could not find root component');
  }

  function buildSubtree(component, components, zLevels) {
    if (processedComponents.has(component)) return null;
    processedComponents.add(component);

    const node = {
      flow: components[component]?.flow || 'default',
      level: Object.entries(zLevels).find(([_, comps]) => comps.includes(component))?.[0] || 0
    };

    // Apply inherited properties
    if (components[component]?.inherits) {
      const parent = components[component].inherits.parent;
      components[component].inherits.properties.forEach(prop => {
        if (!node[prop] && components[parent]?.[prop]) {
          node[prop] = { ...components[parent][prop], inherited: true };
        }
      });
    }

    // Add core properties
    ['position', 'span', 'template', 'distribution', 'area'].forEach(prop => {
      if (components[component]?.[prop]) {
        node[prop] = components[component][prop];
      }
    });

    // Add inheritance
    if (components[component]?.inherits) {
      node.inherits = components[component].inherits;
    }

    // Add affects relationships
    if (components[component]?.affects) {
      node.affects = components[component].affects;
    }

    // Add grid areas if this is a grid container
    if (gridAreas[component]) {
      node.gridAreas = gridAreas[component].areas;
    }

    // Find children
    const childComponents = Object.entries(zLevels)
      .filter(([level, _]) => Number(level) > Number(node.level))
      .flatMap(([_, comps]) => comps)
      .filter(comp => !processedComponents.has(comp));

    if (childComponents.length > 0) {
      node.contains = {};
      childComponents.forEach(child => {
        const subtree = buildSubtree(child, components, zLevels);
        if (subtree) node.contains[child] = subtree;
      });
    }

    return node;
  }

  // Build main tree
  tree.componentTree[rootComponent] = buildSubtree(rootComponent, components, zLevels);

  // Build overlay tree (components with fixed position)
  Object.entries(components)
    .filter(([_, props]) => props.position === 'fixed')
    .forEach(([component, _]) => {
      if (!processedComponents.has(component)) {
        tree.overlayTree[component] = buildSubtree(component, components, zLevels);
      }
    });

  // Add grid area references to the tree
  Object.entries(gridAreas).forEach(([gridComponent, areaInfo]) => {
    if (tree.componentTree[gridComponent] ||
        Object.values(tree.componentTree).some(comp => comp.contains?.[gridComponent])) {
      const gridNode = tree.componentTree[gridComponent] ||
                      Object.values(tree.componentTree)
                        .find(comp => comp.contains?.[gridComponent])
                        ?.contains?.[gridComponent];
      if (gridNode) {
        gridNode.gridAreas = areaInfo.areas;
      }
    }
  });

  return tree;
}

function extractUnifiedMap(cssFiles) {
  let allCssContent = '';
  cssFiles.forEach(file => {
    allCssContent += fs.readFileSync(file, 'utf8');
  });

  const zLevels = extractZLevels(allCssContent);
  const components = extractFlowAndPosition(allCssContent);
  const unifiedMap = buildComponentTree(components, zLevels);

  return unifiedMap;
}

