// Form values initialization function
const initializeFormValues = () => {
  return Object.keys(propertyMapping).reduce((values, key) => {
    let stepValue = (typeof defaultValues[key] === 'number' && !selectOptionsMapping[key])
    ? Math.round((defaultValues[key] * 0.20) * 1000) / 1000 // Default step calculation with 20% rule, keeping up to 3 decimal places
    : '';

    values[key] = {
      id: key,
      value: defaultValues[key] !== undefined ? defaultValues[key] : '',
      type: selectOptionsMapping[key] ? 'select' : (typeof defaultValues[key] === 'number' ? 'number' : 'text'),
      label: propertyMapping[key],
      placeholder: defaultValues[key] !== undefined ? defaultValues[key] : '',
      step: stepValue,
      options: selectOptionsMapping[key] || [],
      remarks: "",
      remarksStyle: { color: '#007bff !important' },
      efficacyPeriod: {
        start: {
          value: 0,
          type: 'number',
          label: 'Start',
          step: 1,
          min: 0,
          max: 1000,
        },
        end: {
          value: defaultValues['plantLifetimeAmount10'],
          type: 'number',
          label: 'End',
          step: 1,
          min: 0,
          max: 1000,
        }
      }
    };

    return values;
  }, {});
};

// Main hook implementation
const useFormValues = () => {
  // State for custom mapping that can be modified
  const [customPropertyMapping, setCustomPropertyMapping] = useState(() => {
    const savedMapping = localStorage.getItem('customPropertyMapping');
    return savedMapping ? JSON.parse(savedMapping) : propertyMapping;
  });

  // Maintain history of label changes
  const [labelHistory, setLabelHistory] = useState([]);
  const [formValues, setFormValues] = useState(() => initializeFormValues(customPropertyMapping));
  // Save custom mapping to localStorage whenever it changes
    useEffect(() => {
      localStorage.setItem('customPropertyMapping', JSON.stringify(customPropertyMapping));
    }, [customPropertyMapping]);
  
    const updatePropertyMapping = (itemId, newLabel) => {
      setCustomPropertyMapping(prev => {
        const updated = {
          ...prev,
          [itemId]: newLabel
        };
        
        // Add to history
        setLabelHistory(prev => [...prev, {
          itemId,
          oldLabel: prev[itemId],
          newLabel,
          timestamp: new Date().toISOString()
        }]);
  
        return updated;
      });
    };
    const resetToDefaultMapping = (itemId) => {
      if (itemId) {
        // Reset single item
        setCustomPropertyMapping(prev => ({
          ...prev,
          [itemId]: propertyMapping[itemId]
        }));
      } else {
        // Reset all
        setCustomPropertyMapping(propertyMapping);
      }
    };
  
    const exportCustomMapping = async () => {
      try {
        // Update the backend Python file
        const backendResponse = await fetch('http://localhost:5010/update_property_mapping', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            property_mapping: customPropertyMapping
          })
        });
    
        if (!backendResponse.ok) {
          throw new Error('Failed to update backend property mapping');
        }
    
        // Update the UseFormValues.js file
        const frontendResponse = await fetch('http://localhost:5010/update_frontend_mapping', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            property_mapping: customPropertyMapping,
            file_path: 'C:/Users/md8w7/OneDrive University of Missouri/Desktop/ImportantFiles/Milestone4/src/hooks/UseFormValues.js'
          })
        });
    
        if (!frontendResponse.ok) {
          throw new Error('Failed to update frontend property mapping');
        }
    
        // Maintain existing backup file creation behavior
        const exportData = {
          mapping: customPropertyMapping,
          history: labelHistory,
          exportDate: new Date().toISOString()
        };
        
        const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'custom-property-mapping.json';
        a.click();
        URL.revokeObjectURL(url);
    
        return true;
      } catch (error) {
        console.error('Error exporting mapping:', error);
        return false;
      }
    };
    const importCustomMapping = async (file) => {
      try {
        const text = await file.text();
        const importedData = JSON.parse(text);
        
        if (importedData.mapping) {
          setCustomPropertyMapping(importedData.mapping);
          if (importedData.history) {
            setLabelHistory(prev => [...prev, ...importedData.history]);
          }
          return true;
        }
        return false;
      } catch (error) {
        console.error('Error importing mapping:', error);
        return false;
      }
    };
  
    // Extend handleInputChange to work with custom mapping
    const handleInputChange = (e, id, type, subType = null) => {
      let { value } = e.target;
  
      if (type === 'number') {
        value = parseFloat(value);
        if (isNaN(value)) {
          value = null;
        }
      }
  
      if (type === 'label') {
        updatePropertyMapping(id, value);
      }
  
      setFormValues(prevValues => {
        if (subType) {
          return {
            ...prevValues,
            [id]: {
              ...prevValues[id],
              [type]: {
                ...prevValues[id][type],
                [subType]: {
                  ...prevValues[id][type][subType],
                  value: value
                }
              }
            }
          };
        } else {
          return {
            ...prevValues,
            [id]: {
              ...prevValues[id],
              [type]: value
            }
          };
        }
      });
    };
    const resetFormItemValues = () => {
      setFormValues(initializeFormValues());
    };
  
    const handleReset = () => {
      resetFormItemValues();
    };
    return {
      formValues,
      handleReset,
      handleInputChange,
      setFormValues,
      customPropertyMapping,
      updatePropertyMapping,
      resetToDefaultMapping,
      exportCustomMapping,
      importCustomMapping,
      labelHistory,
      propertyMapping: customPropertyMapping, // Use custom mapping as primary reference
      iconMapping
    };
  };
  
