### Package Source Security Configuration

class PackageSourceManager {
    [string]$ConfigRoot
    [hashtable]$TrustedSources
    [System.Security.Cryptography.X509Certificates.X509Certificate2]$SecurityCert

    PackageSourceManager([string]$configPath) {
        $this.ConfigRoot = $configPath
        $this.InitializeTrustedSources()
        $this.ValidateSecurityCertificates()
    }

    [void]InitializeTrustedSources() {
        # Define trusted package sources with security requirements
        $this.TrustedSources = @{
            NuGet = @{
                Official = "https://api.nuget.org/v3/index.json"
                Corporate = "https://packages.corporate.com/nuget"
                Required_Protocol = "https"
                Verification_Level = "SignatureValidation"
            }
            Npm = @{
                Official = "https://registry.npmjs.org"
                Corporate = "https://npm.corporate.com"
                Required_Protocol = "https"
                Verification_Level = "ChecksumValidation"
            }
            Python = @{
                Official = "https://pypi.org/simple"
                Corporate = "https://pypi.corporate.com"
                Required_Protocol = "https"
                Verification_Level = "HashValidation"
            }
        }
    }

    [void]ValidateSecurityCertificates() {
        # Validate certificates for package sources
        foreach ($source in $this.TrustedSources.Values) {
            $uri = [System.Uri]$source.Corporate
            $cert = Get-ChildItem -Path Cert:\LocalMachine\Root |
                Where-Object {$_.Subject -like "*$($uri.Host)*"}
            
            if (-not $cert) {
                throw "Corporate certificate not found for $($uri.Host)"
            }
        }
    }

    [void]ConfigureNuGetSources() {
        # Configure NuGet package sources with security policies
        $nugetConfig = "$($this.ConfigRoot)\NuGet.Config"
        
        [xml]$config = @"
<?xml version="1.0" encoding="utf-8"?>
<configuration>
    <packageSources>
        <add key="nuget.org" value="$($this.TrustedSources.NuGet.Official)" protocolVersion="3" />
        <add key="Corporate" value="$($this.TrustedSources.NuGet.Corporate)" />
    </packageSources>
    <packageSourceCredentials>
        <Corporate>
            <add key="ValidAuthenticationTypes" value="Basic" />
        </Corporate>
    </packageSourceCredentials>
    <trustedSigners>
        <author name="Microsoft">
            <certificate fingerprint="3F9001EA83C560D712C24CF213C3D312CB3BFF51EE89435D3430BD06B5D0EECE" hashAlgorithm="SHA256" allowUntrustedRoot="false" />
        </author>
    </trustedSigners>
</configuration>
"@
        $config.Save($nugetConfig)
    }

    [void]ConfigureNpmSources() {
        # Configure npm with secure registry settings
        $npmrcPath = "$($this.ConfigRoot)\.npmrc"
        
        @"
registry=$($this.TrustedSources.Npm.Official)
@company:registry=$($this.TrustedSources.Npm.Corporate)
always-auth=true
strict-ssl=true
audit=true
"@ | Set-Content $npmrcPath
    }

    [void]ConfigurePythonSources() {
        # Configure pip with trusted package sources
        $pipConfig = "$($this.ConfigRoot)\pip.conf"
        
        @"
[global]
index-url = $($this.TrustedSources.Python.Corporate)
extra-index-url = $($this.TrustedSources.Python.Official)
trusted-host = pypi.org
               pypi.corporate.com
"@ | Set-Content $pipConfig
    }
}

### Development Environment Configuration

class DevelopmentEnvironmentManager {
    [string]$EnvRoot
    [PackageSourceManager]$PackageSources

    DevelopmentEnvironmentManager([string]$rootPath, [PackageSourceManager]$packageSources) {
        $this.EnvRoot = $rootPath
        $this.PackageSources = $packageSources
    }

    [void]ConfigureDevEnvironment() {
        # Set up development environment with secure defaults
        $this.ConfigureEnvironmentVariables()
        $this.ConfigureSecurityPolicies()
        $this.ConfigureDevTools()
    }

    [void]ConfigureEnvironmentVariables() {
        # Set up environment variables for development
        $envVars = @{
            "DOTNET_ENVIRONMENT" = "Development"
            "NODE_ENV" = "development"
            "PYTHONPATH" = "$($this.EnvRoot)\src"
            "NUGET_PACKAGES" = "$($this.EnvRoot)\.nuget\packages"
            "npm_config_cache" = "$($this.EnvRoot)\.npm"
            "PIP_CACHE_DIR" = "$($this.EnvRoot)\.pip\cache"
        }

        foreach ($var in $envVars.GetEnumerator()) {
            [Environment]::SetEnvironmentVariable(
                $var.Key, 
                $var.Value, 
                [EnvironmentVariableTarget]::User
            )
        }
    }

    [void]ConfigureSecurityPolicies() {
        # Configure security policies for development environment
        $policies = @{
            "EnableLongPaths" = 1
            "DisableAutomaticIndexing" = 1
            "AllowDevelopmentWithoutDevLicense" = 1
        }

        foreach ($policy in $policies.GetEnumerator()) {
            Set-ItemProperty `
                -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" `
                -Name $policy.Key `
                -Value $policy.Value
        }
    }

    [void]ConfigureDevTools() {
        # Configure development tools with secure defaults
        $this.PackageSources.ConfigureNuGetSources()
        $this.PackageSources.ConfigureNpmSources()
        $this.PackageSources.ConfigurePythonSources()
    }
}

### Usage Example

function Initialize-SecureDevelopmentEnvironment {
    param (
        [string]$RootPath = "$env:USERPROFILE\Development",
        [string]$ConfigPath = "$env:USERPROFILE\Development\Config"
    )

    # Create package source manager
    $packageSources = [PackageSourceManager]::new($ConfigPath)

    # Create development environment manager
    $devEnv = [DevelopmentEnvironmentManager]::new($RootPath, $packageSources)

    # Configure environment
    $devEnv.ConfigureDevEnvironment()
}

