    # Check MSBuild props and targets
    $buildFiles = @(
        "Directory.Build.props",
        "Directory.Build.targets",
        "*.props",
        "*.targets"
    )
    
    foreach ($pattern in $buildFiles) {
        $files = Get-ChildItem -Path $this.Config.ProjectRoot -Filter $pattern -Recurse
